function moduleId(kind){const map={natural:`natural_${s.naturalness}`,register:`register_${s.register}`,profanity:`profanity_${s.profanity}`,proseStyle:`prose_${s.proseStyle}`,pov:`pov_${s.pov}`,length:`length_${s.length}`,detail:`detail_${s.detail}`,dialogue:`dialogue_${s.dialogue}`,innerWorld:`inner_${s.innerWorld}`,scenePacing:`directing_${s.scenePacing}`};return map[kind]||kind;}
function openEditor(id){if(!M[id])return;editingId=id;$('#mpl-editor').hidden=false;$('#mpl-editor-title').textContent=M[id].label;$('#mpl-editor-help').textContent=M[id].help;showMode(false);$('#mpl-editor').scrollIntoView({behavior:'smooth',block:'nearest'});}
function showMode(factory){factoryView=factory;const ta=$('#mpl-editor-text');$('#mpl-tab-user').classList.toggle('mpl-selected',!factory);$('#mpl-tab-factory').classList.toggle('mpl-selected',factory);$('#mpl-factory-note').hidden=!factory;$('#mpl-save-edit').disabled=factory;ta.readOnly=factory;ta.value=factory?M[editingId].prompt:p(editingId);}
function bind(){
  const bindCheck=(id,key)=>{ const el=$(id); if(el) el.addEventListener('change',e=>{s[key]=e.target.checked;save();inject();}); };
  const bindSelect=(id,key)=>{ const el=$(id); if(el) el.addEventListener('change',e=>{s[key]=e.target.value;save();inject();}); };
  [['#mpl-enabled','enabled'],['#mpl-speech-enabled','speechEnabled'],['#mpl-prose-enabled','proseEnabled'],['#mpl-life-enabled','lifeEnabled'],['#mpl-world-enabled','worldEnabled'],['#mpl-relationships-enabled','relationshipsEnabled'],['#mpl-directing-enabled','directingEnabled'],['#mpl-distinct','distinctVoices'],['#mpl-imperfect','imperfectSpeech'],['#mpl-show','showDontTell'],['#mpl-sensory','sensory'],['#mpl-antiecho','antiEcho'],['#mpl-trust-inertia','trustInertia'],['#mpl-conflict-memory','conflictMemory'],['#mpl-earned-vulnerability','earnedVulnerability'],['#mpl-intimacy-continuity','intimacyContinuity'],['#mpl-relationship-bidirectional','relationshipBidirectional'],['#mpl-calm-scenes','calmScenes'],['#mpl-character-momentum','characterMomentum'],['#mpl-offscreen-continuity','offscreenContinuity'],['#mpl-causality','causality'],['#mpl-scene-state','sceneState'],['#mpl-natural-pauses','naturalPauses'],['#mpl-no-premature-close','noPrematureClose'],['#mpl-timeskip','timeSkipDiscipline']].forEach(([id,key])=>bindCheck(id,key));
  const bindRange=(id,key)=>{const el=$(id);if(el)el.addEventListener('input',e=>{s[key]=Number(e.target.value);const o=$(id+'-value');if(o)o.textContent=e.target.value;save();inject();});};
  [['#mpl-humanity','humanity'],['#mpl-emotional-depth','emotionalDepth'],['#mpl-initiative','initiative'],['#mpl-npc-activity','npcActivity'],['#mpl-world-life','worldLife'],['#mpl-everyday-randomness','everydayRandomness']].forEach(([id,key])=>bindRange(id,key));
  [['#mpl-natural','naturalness'],['#mpl-register','register'],['#mpl-profanity','profanity'],['#mpl-prose-style','proseStyle'],['#mpl-pov','pov'],['#mpl-length','length'],['#mpl-detail','detail'],['#mpl-dialogue','dialogue'],['#mpl-inner','innerWorld'],['#mpl-world-setting','worldSetting'],['#mpl-relationship-pace','relationshipPace'],['#mpl-scene-pacing','scenePacing']].forEach(([id,key])=>bindSelect(id,key));
  $('#mpl-world-note')?.addEventListener('input',e=>{s.worldNote=e.target.value;save();inject();});
  $$('.mpl-section:not(.mpl-disabled-section) .mpl-section-head').forEach((button)=>{
    button.addEventListener('click',()=>{
      const sec=button.closest('.mpl-section'); const name=sec.dataset.section; const was=sec.classList.contains('open');
      $$('.mpl-section').forEach(x=>x.classList.remove('open'));
      if(!was){sec.classList.add('open');s.openSection=name;} else s.openSection='';
      save();
    });
  });
  $$('.mpl-pencil[data-kind]').forEach((button)=>{button.addEventListener('click',()=>openEditor(moduleId(button.dataset.kind)));});
  $$('.mpl-pencil[data-edit]').forEach((button)=>{button.addEventListener('click',()=>openEditor(button.dataset.edit));});
  $('#mpl-editor-close')?.addEventListener('click',()=>{$('#mpl-editor').hidden=true;});
  $('#mpl-tab-user')?.addEventListener('click',()=>showMode(false));
  $('#mpl-tab-factory')?.addEventListener('click',()=>showMode(true));
  $('#mpl-save-edit')?.addEventListener('click',()=>{if(!editingId)return;s.overrides[editingId]=$('#mpl-editor-text').value;save();inject();toastr.success('My Preset Life: твоя версия сохранена');});
  $('#mpl-copy-factory')?.addEventListener('click',()=>{showMode(false);$('#mpl-editor-text').value=M[editingId].prompt;});
  $('#mpl-reset-edit')?.addEventListener('click',()=>{delete s.overrides[editingId];save();showMode(false);inject();toastr.info('Вернула заводской prompt');});
}
function sync(){const checks={enabled:'mpl-enabled',speechEnabled:'mpl-speech-enabled',proseEnabled:'mpl-prose-enabled',lifeEnabled:'mpl-life-enabled',worldEnabled:'mpl-world-enabled',relationshipsEnabled:'mpl-relationships-enabled',distinctVoices:'mpl-distinct',imperfectSpeech:'mpl-imperfect',showDontTell:'mpl-show',sensory:'mpl-sensory',antiEcho:'mpl-antiecho',trustInertia:'mpl-trust-inertia',conflictMemory:'mpl-conflict-memory',earnedVulnerability:'mpl-earned-vulnerability',intimacyContinuity:'mpl-intimacy-continuity',relationshipBidirectional:'mpl-relationship-bidirectional',directingEnabled:'mpl-directing-enabled',calmScenes:'mpl-calm-scenes',characterMomentum:'mpl-character-momentum',offscreenContinuity:'mpl-offscreen-continuity',causality:'mpl-causality',sceneState:'mpl-scene-state',naturalPauses:'mpl-natural-pauses',noPrematureClose:'mpl-no-premature-close',timeSkipDiscipline:'mpl-timeskip'};for(const[k,id]of Object.entries(checks))$('#'+id).checked=!!s[k];const sels={naturalness:'mpl-natural',register:'mpl-register',profanity:'mpl-profanity',proseStyle:'mpl-prose-style',pov:'mpl-pov',length:'mpl-length',detail:'mpl-detail',dialogue:'mpl-dialogue',innerWorld:'mpl-inner',worldSetting:'mpl-world-setting',relationshipPace:'mpl-relationship-pace',scenePacing:'mpl-scene-pacing'};for(const[k,id]of Object.entries(sels))$('#'+id).value=s[k];const ranges={humanity:'mpl-humanity',emotionalDepth:'mpl-emotional-depth',initiative:'mpl-initiative',npcActivity:'mpl-npc-activity',worldLife:'mpl-world-life',everydayRandomness:'mpl-everyday-randomness'};for(const[k,id]of Object.entries(ranges)){const el=$('#'+id),o=$('#'+id+'-value');if(el)el.value=s[k];if(o)o.textContent=s[k];}const wn=$('#mpl-world-note');if(wn)wn.value=s.worldNote||'';if(s.openSection)$(`.mpl-section[data-section="${s.openSection}"]`)?.classList.add('open');update();}
function update(){const out=$('#mpl-preview');if(!out)return;out.textContent=assembled()||'Ничего не отправляется модели: Engine или все модули выключены.';const n=allIds().length?allIds().length-1:0;$('#mpl-active-count').textContent=`Активно: ${n}`;$('#mpl-speech-summary').textContent=s.speechEnabled?`${speechIds().length} активно`:'выкл.';$('#mpl-prose-summary').textContent=s.proseEnabled?`${M[`prose_${s.proseStyle}`]?.label.replace('Стиль · ','')||''} · ${proseIds().length} активно`:'выкл.';$('#mpl-life-summary').textContent=s.lifeEnabled?`${lifeIds().length} активно`:'выкл.';const wid=`world_${s.worldSetting}`;$('#mpl-world-summary').textContent=s.worldEnabled?(M[wid]?.label.replace('Мир · ','')||'настроено'):'выкл.';const rid=`relationship_${s.relationshipPace}`;$('#mpl-relationships-summary').textContent=s.relationshipsEnabled?`${M[rid]?.label.replace('Отношения · ','')||'настроено'} · ${relationshipIds().length} активно`:'выкл.';const did=`directing_${s.scenePacing}`;$('#mpl-directing-summary').textContent=s.directingEnabled?`${M[did]?.label.replace('Режиссура · ','')||'настроено'} · ${directingIds().length} активно`:'выкл.';}
function init(){
  try {
    load();
    create();
    inject();
    let tries=0;
    const t=setInterval(()=>{
      try { create(); } catch(e) { console.error('[My Preset Life] panel retry failed',e); }
      if($('#my-preset-life-settings')||++tries>40) clearInterval(t);
    },500);
    console.log(`[My Preset Life] v${VERSION} loaded`);
  } catch(e) {
    console.error('[My Preset Life] startup failed',e);
    // Last-resort panel retry: if settings host appears later, try again without hiding the failure.
    let tries=0;
    const t=setInterval(()=>{
      try { if(!s) load(); create(); if($('#my-preset-life-settings')) clearInterval(t); }
      catch(err){ console.error('[My Preset Life] recovery retry failed',err); }
      if(++tries>40) clearInterval(t);
    },500);
  }
}
jQuery(init);
